#!/usr/bin/env python3

"""
Test the check_pdftool function to understand the issue
"""

import subprocess
import sys
import os

# Add current directory to path
sys.path.insert(0, '.')

from paper2remarkable.utils import check_pdftool, NoPDFToolError

def test_check_pdftool_scenarios():
    """Test various scenarios for check_pdftool function"""

    print("=== Testing check_pdftool function ===")

    # Scenario 1: Both tools available - should prefer pdftk
    try:
        result = check_pdftool("pdftk", "qpdf")
        print(f"Scenario 1 - Both available: {result}")
    except Exception as e:
        print(f"Scenario 1 - Error: {e}")

    # Scenario 2: pdftk not available, qpdf available - should use qpdf
    try:
        result = check_pdftool("/nonexistent/fake_pdftk", "qpdf") 
        print(f"Scenario 2 - pdftk missing, qpdf available: {result}")
    except Exception as e:
        print(f"Scenario 2 - Error: {e}")

    # Scenario 3: qpdf not available, pdftk available - should use pdftk
    try:
        result = check_pdftool("pdftk", "/nonexistent/fake_qpdf")
        print(f"Scenario 3 - qpdf missing, pdftk available: {result}")
    except Exception as e:
        print(f"Scenario 3 - Error: {e}")

    # Scenario 4: Both tools missing - should raise NoPDFToolError
    try:
        result = check_pdftool("/nonexistent/fake_pdftk", "/nonexistent/fake_qpdf")
        print(f"Scenario 4 - Both missing: {result}")
    except NoPDFToolError as e:
        print(f"Scenario 4 - NoPDFToolError raised correctly: {e}")
    except Exception as e:
        print(f"Scenario 4 - Unexpected error: {e}")

def test_subprocess_behavior():
    """Test how subprocess behaves with missing executables"""
    print("\n=== Testing subprocess behavior ===")

    # Test calling a non-existent command
    try:
        result = subprocess.call(["/nonexistent/fake_command"])
        print(f"Non-existent command returned: {result}")
    except FileNotFoundError as e:
        print(f"FileNotFoundError for non-existent command: {e}")
    except Exception as e:
        print(f"Other error for non-existent command: {e}")

if __name__ == "__main__":
    test_check_pdftool_scenarios()
    test_subprocess_behavior()

