#!/usr/bin/env python3

"""
Test provider initialization with missing pdftk to ensure our fix works in context
"""

import sys
import os
import tempfile

# Add the package to path
sys.path.insert(0, '.')

def test_base_provider_with_missing_pdftk():
    """Test that Base provider can initialize even when pdftk is missing"""

    print("=== Testing Provider Initialization ===")

    try:
        from paper2remarkable.providers._base import Provider

        # Create a dummy provider class for testing
        class DummyProvider(Provider):
            @staticmethod
            def validate(src):
                return True

            def get_abs_pdf_urls(self, src):
                return "http://example.com", "http://example.com/file.pdf"

        print("✅ Successfully imported Provider classes")

        # Test 1: Normal initialization (both tools available)
        try:
            with tempfile.TemporaryDirectory() as tmpdir:
                prov = DummyProvider(
                    verbose=False,
                    upload=False,
                    pdftk_path="pdftk",
                    qpdf_path="qpdf"
                )
                print(f"✅ Normal init - pdftool selected: {prov.pdftool}")
        except Exception as e:
            print(f"❌ Normal init failed: {e}")

        # Test 2: pdftk missing, qpdf available (this should work with our fix)
        try:
            with tempfile.TemporaryDirectory() as tmpdir:
                prov = DummyProvider(
                    verbose=False,
                    upload=False,
                    pdftk_path="/nonexistent/pdftk",
                    qpdf_path="qpdf"
                )
                print(f"✅ Missing pdftk handled - pdftool selected: {prov.pdftool}")
                if prov.pdftool == "qpdf":
                    print("✅ Correctly fell back to qpdf")
                else:
                    print(f"❌ Expected qpdf, got {prov.pdftool}")
        except Exception as e:
            print(f"❌ Missing pdftk test failed: {e}")

        # Test 3: Both tools missing
        try:
            with tempfile.TemporaryDirectory() as tmpdir:
                prov = DummyProvider(
                    verbose=False,
                    upload=False,
                    pdftk_path="/nonexistent/pdftk",
                    qpdf_path="/nonexistent/qpdf"
                )
            print("❌ Should have raised NoPDFToolError")
        except Exception as e:
            if "Neither pdftk or qpdf could be found" in str(e):
                print("✅ Correctly raised NoPDFToolError when both missing")
            else:
                print(f"❌ Wrong error for missing tools: {e}")

    except ImportError as e:
        print(f"❌ Import error: {e}")
    except Exception as e:
        print(f"❌ Other error: {e}")

if __name__ == "__main__":
    test_base_provider_with_missing_pdftk()
